function box(x,y,w,h){return`<g filter="url(#wcs)"><rect x="${x}" y="${y-h}" width="${w}" height="${h}" fill="#b98a55"/><rect x="${x}" y="${y-h}" width="${w}" height="10" fill="#9b6f40"/><path d="M${x+6},${y-h} q${w*.25},-14 ${w*.5},-4 q${w*.25},-12 ${w*.46},2" stroke="#e8c676" stroke-width="7" fill="none" stroke-linecap="round"/></g>`}
function room(wall="#e9c8a4",floor="#a8714a"){return`<rect width="800" height="600" fill="${wall}" filter="url(#wc)"/>${[0,1,2,3,4,5,6,7,8].map(i=>`<rect x="${i*100}" y="0" width="2" height="440" fill="rgba(120,70,40,.12)"/>`).join("")}<rect y="440" width="800" height="160" fill="${floor}" filter="url(#wc)"/><rect y="436" width="800" height="10" fill="#7a4a30"/>`}
function winIn(x,y,w,h,kind="night"){return`<g filter="url(#wcs)"><rect x="${x-10}" y="${y-10}" width="${w+20}" height="${h+20}" fill="#f4ead6"/><rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${kind==="night"?"#1d2a55":"#bcd2ee"}"/></g>${kind==="night"?`<circle cx="${x+w*.72}" cy="${y+h*.28}" r="${w*.08}" fill="#fff4dc"/>`:""}<path d="M${x},${y+h} L${x},${y+h*.75} Q${x+w*.3},${y+h*.62} ${x+w*.6},${y+h*.74} T${x+w},${y+h*.7} V${y+h}Z" fill="#e8ecf4"/>${spruce(x+w*.25,y+h*.8,h*.4,"#203248",true)}<rect x="${x+w/2-3}" y="${y}" width="6" height="${h}" fill="#f4ead6"/><rect x="${x}" y="${y+h/2-3}" width="${w}" height="6" fill="#f4ead6"/><rect x="${x-18}" y="${y+h+8}" width="${w+36}" height="12" rx="4" fill="#7a4a30"/>`}
function rocking(x,y){return`<g filter="url(#wcs)"><path d="M${x-80},${y} Q${x},${y+26} ${x+80},${y-6}" stroke="#7a4a30" stroke-width="9" fill="none" stroke-linecap="round"/><rect x="${x-56}" y="${y-70}" width="10" height="70" fill="#8a5636"/><rect x="${x+34}" y="${y-70}" width="10" height="70" fill="#8a5636"/><rect x="${x-62}" y="${y-78}" width="112" height="14" rx="5" fill="#8a5636"/><path d="M${x+36},${y-74} L${x+56},${y-200}" stroke="#8a5636" stroke-width="12" stroke-linecap="round"/><path d="M${x+60},${y-74} L${x+78},${y-196}" stroke="#8a5636" stroke-width="8" stroke-linecap="round"/></g>`}
function granSeated(x,y,o={}){return`<g filter="url(#wcs)"><path d="M${x-40},${y-74} C${x-48},${y-150} ${x+30},${y-170} ${x+44},${y-110} L${x+40},${y-70}Z" fill="#5c6f9e"/><path d="M${x-58},${y-80} Q${x-10},${y-96} ${x+40},${y-76} L${x+42},${y-60} Q${x-10},${y-70} ${x-60},${y-62}Z" fill="#7b4f7d"/><rect x="${x-62}" y="${y-66}" width="14" height="66" rx="6" fill="#33304a"/><rect x="${x-40}" y="${y-66}" width="14" height="66" rx="6" fill="#33304a"/>
  <path d="M${x-30},${y-150} Q${x+4},${y-118} ${x+38},${y-150} L${x+34},${y-160} Q${x+4},${y-136} ${x-26},${y-160}Z" fill="#d39b3d"/></g><g class="head2" filter="url(#wcs)">${face(x+4,y-182,24,SKIN[3],"#d6d2dc",{bun:true,glasses:true})}</g>
  <g class="knit"><path d="M${x-34},${y-108} L${x+6},${y-128}" stroke="#c9b28a" stroke-width="3.5"/><path d="M${x-30},${y-128} L${x+10},${y-104}" stroke="#c9b28a" stroke-width="3.5"/></g><path d="M${x-26},${y-112} q14,10 30,0 l-2,22 q-14,6 -26,0z" fill="${o.knit||"#b23a2e"}" filter="url(#wcs)"/><path d="M${x-50},${y-114} q-10,-6 -16,-20" stroke="#5c6f9e" stroke-width="14" fill="none" stroke-linecap="round"/><path d="M${x+30},${y-140} q-10,20 -24,30" stroke="#5c6f9e" stroke-width="14" fill="none" stroke-linecap="round"/>`}
function yarn(x,y,r,col){return`<g filter="url(#wcs)"><circle cx="${x}" cy="${y}" r="${r}" fill="${col}"/><path d="M${x-r*.7},${y-r*.4} q${r*.7},${r*.6} ${r*1.4},0 M${x-r*.8},${y+r*.1} q${r*.8},${r*.6} ${r*1.6},0" stroke="${shade(col,.7)}" stroke-width="2" fill="none"/></g>`}
function lampIn(x,y){return`<circle cx="${x}" cy="${y}" r="160" fill="url(#warmIn)" class="flk"/><path d="M${x-30},${y-10} L${x+30},${y-10} L${x+18},${y-40} L${x-18},${y-40}Z" fill="#e8b04a" filter="url(#wcs)"/><rect x="${x-3}" y="${y-10}" width="6" height="${440-y+10}" fill="#5a4040"/>`}
function school(x,y,w,h){let s=`<g filter="url(#wc)"><rect x="${x}" y="${y-h}" width="${w}" height="${h}" fill="#b5503f"/><path d="M${x-12},${y-h+4} L${x+w/2},${y-h-60} L${x+w+12},${y-h+4}Z" fill="#3b2f3f"/><path d="M${x-14},${y-h+2} L${x+w/2},${y-h-64} L${x+w+14},${y-h+2} L${x+w+4},${y-h+10} L${x+w/2},${y-h-52} L${x-4},${y-h+10}Z" fill="#f6f2ea"/><circle cx="${x+w/2}" cy="${y-h-14}" r="14" fill="#f4ead6"/><path d="M${x+w/2},${y-h-24} V${y-h-14} H${x+w/2+7}" stroke="#3b2f3f" stroke-width="2.5" fill="none"/></g>`;
  const n=Math.floor(w/56);for(let i=0;i<n;i++){const wx=x+28+i*((w-56)/(n-1||1));s+=`<g filter="url(#wcs)"><rect x="${wx-14}" y="${y-h+22}" width="28" height="32" fill="#ffd98a" stroke="#f4ead6" stroke-width="4"/></g>`}return s}
function lantern(x,y,s=1){return`<circle cx="${x}" cy="${y}" r="${50*s}" fill="url(#winB)" class="flk"/><g filter="url(#wcs)"><rect x="${x-12*s}" y="${y-16*s}" width="${24*s}" height="${30*s}" rx="${4*s}" fill="#3b2f3f"/><rect x="${x-8*s}" y="${y-12*s}" width="${16*s}" height="${22*s}" fill="#ffd27a"/><path d="M${x-8*s},${y-16*s} q${8*s},-${14*s} ${16*s},0" stroke="#3b2f3f" stroke-width="${3*s}" fill="none"/></g>`}
function canLantern(x,y,s=1){rs(Math.round(x));let d="";for(let i=0;i<14;i++)d+=`<circle class="tw" cx="${x+(R()-.5)*120*s}" cy="${y+12*s+R()*30*s}" r="${2+R()*2}" fill="#ffe3a0" style="animation-delay:${(R()*3).toFixed(1)}s"/>`;
  return`<circle cx="${x}" cy="${y}" r="${44*s}" fill="url(#winB)" class="flk"/>${d}<g filter="url(#wcs)"><rect x="${x-12*s}" y="${y-16*s}" width="${24*s}" height="${30*s}" fill="#b9bfcc"/>${[0,1,2,3,4,5].map(i=>`<circle cx="${x-6*s+(i%3)*6*s}" cy="${y-8*s+Math.floor(i/3)*12*s}" r="${1.6*s}" fill="#ffd27a"/>`).join("")}<path d="M${x-12*s},${y-16*s} q${12*s},-${18*s} ${24*s},0" stroke="#7d828f" stroke-width="${2.4*s}" fill="none"/></g>`}
function dog(x,y,s,o={}){const f=o.flip?-1:1;return`<g transform="translate(${x} ${y}) scale(${s*f} ${s})" filter="url(#wcs)"><ellipse cx="0" cy="2" rx="50" ry="8" fill="rgba(60,50,90,.18)"/><rect x="-34" y="-30" width="12" height="30" rx="5" fill="#7d7f8f"/><rect x="18" y="-30" width="12" height="30" rx="5" fill="#7d7f8f"/><g class="breath"><ellipse cx="0" cy="-40" rx="44" ry="22" fill="#8e909e"/><circle cx="-12" cy="-44" r="6" fill="#6b6d7b"/><circle cx="12" cy="-36" r="5" fill="#6b6d7b"/></g><path class="wag" d="M-40,-46 q-24,-14 -20,-36" stroke="#8e909e" stroke-width="9" fill="none" stroke-linecap="round" style="transform-origin:-40px -46px"/>
  <g class="head2"><ellipse cx="44" cy="-64" rx="22" ry="19" fill="#8e909e"/><ellipse cx="62" cy="-58" rx="10" ry="8" fill="#a4a6b3"/><circle cx="70" cy="-60" r="4" fill="#2a2433"/><circle cx="46" cy="-68" r="3" fill="#2a2433"/><path d="M30,-80 l-4,-26 l14,18z" fill="#6b6d7b"/><path d="M50,-80 q14,4 12,24 q-8,-10 -16,-14z" fill="#6b6d7b"/>${o.leash?`<rect x="28" y="-52" width="22" height="6" rx="3" fill="#b23a2e"/>`:""}</g></g>`}
function mouse(x,y,s){return`<g transform="translate(${x} ${y}) scale(${s})" filter="url(#wcs)"><ellipse cx="0" cy="2" rx="40" ry="7" fill="rgba(60,50,90,.18)"/><path d="M-30,-10 q-30,6 -40,-14" stroke="#8a7b84" stroke-width="4" fill="none"/><g class="breath"><ellipse cx="0" cy="-22" rx="32" ry="24" fill="#a3949c"/><ellipse cx="4" cy="-14" rx="18" ry="12" fill="#c9bcc2"/></g><g class="head2"><circle cx="26" cy="-40" r="17" fill="#a3949c"/><circle cx="16" cy="-58" r="11" fill="#c9a2ac"/><circle cx="34" cy="-56" r="9" fill="#c9a2ac"/><circle cx="32" cy="-42" r="2.6" fill="#2a2433"/><circle cx="43" cy="-36" r="3.4" fill="#d77a8a"/><rect x="-14" y="-52" width="32" height="10" rx="5" fill="#b23a2e"/></g></g>`}

