function board(x,y,w,h,txt="",col="#2f4a3f",tc="#f4f1ea",fs=34){return`<g filter="url(#wc)"><rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${col}"/><rect x="${x-10}" y="${y-10}" width="${w+20}" height="12" fill="#8a5636"/><rect x="${x}" y="${y+h}" width="${w}" height="8" fill="#8a5636"/></g>${txt?`<text x="${x+24}" y="${y+h*.45}" font-family="Fredoka" font-size="${fs}" fill="${tc}" opacity=".88">${txt}</text>`:""}`}
function desk(x,y,w=170){return`<g filter="url(#wcs)"><rect x="${x}" y="${y}" width="${w}" height="16" rx="4" fill="#c79a62"/><rect x="${x+10}" y="${y+16}" width="8" height="${440-y+30}" fill="#8a6a48"/><rect x="${x+w-18}" y="${y+16}" width="8" height="${440-y+30}" fill="#8a6a48"/></g>`}
function classroom(night){return room("#e6d9bf","#a8714a")+winIn(520,80,220,170,night?"night":"day")+board(60,70,380,180)}
function pLantern(x,y,s,col="#f4e2b0",glow=true){rs(Math.round(x+y));let d="";for(let i=0;i<9;i++)d+=`<path transform="translate(${x+(R()-.5)*30*s} ${y-10*s-R()*44*s})" d="${starPath(3.4*s)}" fill="#fff3c0"/>`;return`${glow?`<circle cx="${x}" cy="${y-30*s}" r="${70*s}" fill="url(#winB)" class="flk"/>`:""}<g filter="url(#wcs)"><rect x="${x-22*s}" y="${y-64*s}" width="${44*s}" height="${64*s}" rx="${5*s}" fill="${col}" stroke="${shade(col,.75)}" stroke-width="2"/></g>${d}`}
function mush(x,y,col){return`<g filter="url(#wcs)"><path d="M${x-26},${y} q6,-22 18,-14 q10,-16 22,-2 q10,-8 14,16z" fill="${col}" opacity=".85"/><path d="M${x-24},${y} q24,8 50,0" stroke="${shade(col,.7)}" stroke-width="3" fill="none"/></g>`}
function shelf(x,y,w){return`<g filter="url(#wcs)"><rect x="${x}" y="${y}" width="${w}" height="12" fill="#8a5636"/><rect x="${x}" y="${y+12}" width="${w}" height="5" fill="#6b4126"/></g>`}
function cans(x,y,n,s=1){let o="";for(let i=0;i<n;i++)o+=`<g filter="url(#wcs)"><rect x="${x+i*30*s}" y="${y-38*s-(i%2)*4}" width="${24*s}" height="${38*s}" fill="#b9bfcc" stroke="#8a909e" stroke-width="2"/><ellipse cx="${x+i*30*s+12*s}" cy="${y-38*s-(i%2)*4}" rx="${12*s}" ry="${4*s}" fill="#dfe3ea"/></g>`;return o}
function hammer(x,y,r=0,cls=""){return`<g transform="translate(${x} ${y}) rotate(${r})" class="${cls}" style="transform-box:fill-box;transform-origin:0% 100%"><rect x="-4" y="-60" width="8" height="60" rx="3" fill="#8a5636"/><rect x="-18" y="-72" width="36" height="16" rx="3" fill="#5a6070"/></g>`}
function txt(x,y,t,fs=24,col="#3b2f3f",cls=""){return`<text x="${x}" y="${y}" font-family="Fredoka" font-size="${fs}" fill="${col}" class="${cls}">${t}</text>`}
function cheeks(x,y,s){return`<circle cx="${x-12*s}" cy="${y}" r="${5*s}" fill="#e88a8a" opacity=".7"/><circle cx="${x+12*s}" cy="${y}" r="${5*s}" fill="#e88a8a" opacity=".7"/>`}
function kickSled(x,y,s){return`<g filter="url(#wcs)"><path d="M${x-60*s},${y} H${x+60*s} q14,0 14,-10" stroke="#3b3e63" stroke-width="${5*s}" fill="none"/><rect x="${x-46*s}" y="${y-40*s}" width="${36*s}" height="${30*s}" fill="#b23a2e"/><path d="M${x-10*s},${y-40*s} L${x+16*s},${y-120*s}" stroke="#8a5636" stroke-width="${7*s}"/><path d="M${x-50*s},${y-40*s} L${x-30*s},${y-120*s}" stroke="#8a5636" stroke-width="${7*s}"/><path d="M${x-34*s},${y-120*s} H${x+22*s}" stroke="#8a5636" stroke-width="${8*s}" stroke-linecap="round"/></g>`}
function door(x,y,w,h,col="#6b4a3a",name=""){return`<g filter="url(#wcs)"><rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${col}"/><rect x="${x+10}" y="${y+12}" width="${w-20}" height="${h*.4}" fill="${shade(col,.85)}"/><rect x="${x+10}" y="${y+h*.5}" width="${w-20}" height="${h*.42}" fill="${shade(col,.85)}"/><circle cx="${x+w-18}" cy="${y+h*.52}" r="5" fill="#e8c676"/></g>${name?`<rect x="${x+w/2-34}" y="${y+28}" width="68" height="20" fill="#f4ead6"/><text x="${x+w/2}" y="${y+43}" text-anchor="middle" font-family="Andika" font-size="13" fill="#3b2f3f">${name}</text>`:""}`}
function stairwell(col="#e3c96a"){return`<rect width="800" height="600" fill="${col}" filter="url(#wc)"/><rect y="0" width="800" height="300" fill="rgba(255,255,255,.12)"/><rect y="440" width="800" height="160" fill="#9a8a7a" filter="url(#wc)"/><rect y="436" width="800" height="8" fill="#6b5a4a"/>`}
function stairs(x,y,n,dx=40,dy=26){let s=`<g filter="url(#wcs)">`;for(let i=0;i<n;i++)s+=`<rect x="${x+i*dx}" y="${y-i*dy}" width="${dx+2}" height="${dy+i*dy}" fill="${i%2?"#b8a898":"#c4b5a5"}"/><rect x="${x+i*dx}" y="${y-i*dy}" width="${dx+2}" height="5" fill="#8a7a6a"/>`;s+=`<path d="M${x},${y-70} L${x+n*dx},${y-70-n*dy}" stroke="#3b2f3f" stroke-width="6"/>`;for(let i=0;i<=n;i+=2)s+=`<rect x="${x+i*dx-2}" y="${y-70-i*dy}" width="4" height="70" fill="#3b2f3f"/>`;return s+"</g>"}
function paperStar(x,y,r,rot=0,cls=""){return`<g transform="translate(${x} ${y}) rotate(${rot})" class="${cls}"><path d="${starPath(r)}" fill="#fbf7ee" stroke="#c9c2b2" stroke-width="1.5"/><path d="M0,0 L0,${-r} M0,0 L${r*.95},${-r*.31} M0,0 L${r*.59},${r*.81} M0,0 L${-r*.59},${r*.81} M0,0 L${-r*.95},${-r*.31}" stroke="#ddd6c6" stroke-width="1"/></g>`}
function paperBird(x,y,s,cls=""){return`<g transform="translate(${x} ${y}) scale(${s})" class="${cls}"><path d="M-30,0 L0,-12 L34,-2 L6,6Z" fill="#fbf7ee" stroke="#c9c2b2" stroke-width="1.5"/><path d="M0,-12 L-6,-34 L10,-4Z" fill="#efe8d8" stroke="#c9c2b2" stroke-width="1.5"/><path d="M34,-2 L44,-16" stroke="#c9c2b2" stroke-width="3"/></g>`}
function heart(x,y,s,col="#c23a2b"){return`<path transform="translate(${x} ${y}) scale(${s})" d="M0,10 C-14,0 -14,-12 -6,-12 C-2,-12 0,-8 0,-6 C0,-8 2,-12 6,-12 C14,-12 14,0 0,10Z" fill="${col}"/>`}
function frame(x,y,w,h,inner){return`<g filter="url(#wcs)"><rect x="${x}" y="${y}" width="${w}" height="${h}" fill="#8a5636"/><rect x="${x+8}" y="${y+8}" width="${w-16}" height="${h-16}" fill="#f4ead6"/></g>${inner}`}
function plant(x,y,s){return`<g filter="url(#wcs)"><path d="M${x-14*s},${y} l4,${-28*s} h${20*s} l4,${28*s}z" fill="#c7703c"/>${[-30,-10,10,30].map(a=>`<ellipse cx="${x+a*.8*s}" cy="${y-44*s}" rx="${9*s}" ry="${22*s}" fill="#4f8a5a" transform="rotate(${a} ${x+a*.8*s} ${y-44*s})"/>`).join("")}</g>`}
function books(x,y,w,h){rs(x);let s=`<g filter="url(#wcs)"><rect x="${x}" y="${y}" width="${w}" height="${h}" fill="#6b4126"/>`;for(let r=0;r<4;r++){let bx=x+8;while(bx<x+w-14){const bw=8+R()*10;s+=`<rect x="${bx}" y="${y+10+r*(h/4)+R()*8}" width="${bw}" height="${h/4-18}" fill="${["#b23a2e","#2f6a6a","#d39b3d","#5c6f9e","#7b4f7d","#e3c9a0"][Math.floor(R()*6)]}"/>`;bx+=bw+2}s+=`<rect x="${x}" y="${y+(r+1)*(h/4)-6}" width="${w}" height="6" fill="#5a3a28"/>`}return s+"</g>"}
function bins(x,y){return`<g filter="url(#wcs)">${[["#3f6a4a","PAPPER"],["#5c6f9e","PLAST"],["#9a6b4a","MAT"]].map(([c,t],i)=>`<rect x="${x+i*110}" y="${y-110}" width="94" height="110" rx="6" fill="${c}"/><rect x="${x+i*110-4}" y="${y-120}" width="102" height="14" rx="4" fill="${shade(c,.7)}"/><text x="${x+i*110+47}" y="${y-60}" text-anchor="middle" font-family="Fredoka" font-size="15" fill="#f4f1ea">${t}</text>`).join("")}</g>`}
function newspaper(x,y,s,rot=0){return`<g transform="translate(${x} ${y}) rotate(${rot}) scale(${s})" filter="url(#wcs)"><rect x="-60" y="-80" width="120" height="160" fill="#efece4"/>${[0,1,2,3,4,5,6].map(i=>`<rect x="-50" y="${-64+i*14}" width="${i%3?100:60}" height="5" fill="#b9b4a8"/>`).join("")}<rect x="-10" y="20" width="56" height="48" fill="#3b2f3f" opacity=".15"/><rect x="-6" y="24" width="48" height="40" fill="#f3f1ec" stroke="#8a8478" stroke-dasharray="4 3"/><rect x="-54" y="54" width="44" height="18" fill="#fff" stroke="#8a8478"/></g>`}
function crossword(x,y,n,sz){let s=`<g filter="url(#wcs)"><rect x="${x-8}" y="${y-8}" width="${n*sz+16}" height="${n*sz+16}" fill="#efece4"/>`;rs(n*7);for(let i=0;i<n;i++)for(let j=0;j<n;j++){const b=R()<.18;s+=`<rect x="${x+i*sz}" y="${y+j*sz}" width="${sz}" height="${sz}" fill="${b?"#3b2f3f":"#fff"}" stroke="#8a8478" stroke-width="1"/>`;if(!b&&R()<.45)s+=`<text x="${x+i*sz+sz*.28}" y="${y+j*sz+sz*.78}" font-family="Andika" font-size="${sz*.62}" fill="#6b6f80">${"AEKLMNORSTÄ"[Math.floor(R()*11)]}</text>`}return s+"</g>"}

