    if(h==="beanie")s+=`<path d="M-18,-268 Q-19,-298 0,-298 Q19,-298 18,-268Z" fill="${col("t")}"/><rect x="-19" y="-274" width="38" height="8" rx="3" fill="${col("t2")}"/><path d="M-16,-266 q-4,14 0,22 M16,-266 q4,14 0,22" stroke="${col("h")}" stroke-width="5" fill="none"/>`;
    if(h==="bun")s+=`<path d="M-17,-266 Q-18,-292 0,-292 Q19,-292 17,-266 Q12,-282 0,-282 Q-12,-282 -17,-266Z" fill="${col("h")}"/><circle cx="0" cy="-292" r="9" fill="${col("h")}"/>`;
