const mSnow=(n,sd)=>{rs(sd);let s="";for(let i=0;i<n;i++){const r=R()*2+.6;s+=`<circle class="fall" cx="${(R()*800).toFixed(0)}" cy="${(R()*600).toFixed(0)}" r="${r.toFixed(1)}" fill="#e8eef8" opacity="${(.35+r*.2).toFixed(2)}" style="animation-duration:${(7+R()*8).toFixed(1)}s;animation-delay:-${(R()*14).toFixed(1)}s"/>`}return s};
const mPine=(x,y,h,col)=>{let d=`M${x},${y-h}`;for(let i=1;i<=7;i++){const yy=y-h+h*i/7,w=h*.3*i/7;d+=` L${x+w},${yy} L${x+w*.4},${yy-h*.03}`}d+=` L${x},${y}`;for(let i=7;i>=1;i--){const yy=y-h+h*i/7,w=h*.3*i/7;d+=` L${x-w*.4},${yy-h*.03} L${x-w},${yy}`}return`<path d="${d}Z" fill="${col}"/>`};
