let MG=0;
const mGrad=(a,b,c)=>{const id="mg"+(++MG);return[id,`<linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${a}"/>${c?`<stop offset=".6" stop-color="${b}"/><stop offset="1" stop-color="${c}"/>`:`<stop offset="1" stop-color="${b}"/>`}</linearGradient>`]};
const mBg=(a,b,c,y=0,h=600)=>{const[id,d]=mGrad(a,b,c);return`<defs>${d}</defs><rect y="${y}" width="800" height="${h}" fill="url(#${id})"/>`};
const mRoomBg=(wall="#3e4558",floor="#2a2622",fy=440)=>mBg(shade(wall,1.12),wall,null,0,fy)+mBg(floor,shade(floor,.7),null,fy,600-fy)+`<rect y="${fy-4}" width="800" height="6" fill="${shade(floor,.6)}"/>`;
